using System;
using System.IO;
using System.Linq;
using UnityEngine;
namespace FrontierAtlas.Editor
{
    public static class IndustrialDefenceValidation
    {
        private static int checks;
        private static void Check(bool condition,string text){if(!condition)throw new InvalidOperationException("INDUSTRIA/SAM: "+text);checks++;}
        private static GeographicPolygon Rect(float west,float east)=>new GeographicPolygon{rings=new[]{new GeographicRing{points=new[]{new Vector2(west,16),new Vector2(east,16),new Vector2(east,128),new Vector2(west,128),new Vector2(west,16)}}}};
        private static TerritorySimulation Fixture(bool water=false)
        {
            var map=new AfricaGeography{west=0,east=256,south=0,north=128,wrapLongitude=false,neutralRegions=water?new[]{Rect(0,123),Rect(130,256)}:new[]{Rect(0,256)},countries=new[]{new CountryDefinition{code="A",name="Alfa",longitude=180,latitude=60,polygons=Array.Empty<GeographicPolygon>()},new CountryDefinition{code="B",name="Beta",longitude=230,latitude=70,polygons=Array.Empty<GeographicPolygon>()}}};
            var g=new TerritorySimulation(new WorldGrid(256,128,27,map),27,0,new MatchOptions{customPlayer=true,advancedSystems=true,playerName="Industria"}){AiEnabled=false,ReinforcementsEnabled=false};g.Rules.factoryConnectionRadius=99;g.Rules.tacticalPassiveIncome=0;g.FoundPlayer(g.World.At(60,60),"Industria");Array.Clear(g.TerritoryCounts,0,g.FactionCount);
            for(int c=0;c<g.Owners.Length;c++){int x=c%256,owner=!g.World.Land[c]?-2:water?g.PlayerFaction:x<128?g.PlayerFaction:x<200?0:1;g.Owners[c]=owner;if(owner>=0)g.TerritoryCounts[owner]++;}g.RebuildCampaignIndexes();for(int f=0;f<g.FactionCount;f++){g.Gold[f]=1e9;g.ProtectionUntil[f]=0;}g.Rules.victoryFraction=1;return g;
        }
        private static void Tick(TerritorySimulation g,float seconds){for(int i=0;i<Mathf.CeilToInt(seconds/.1f);i++)g.Step(.1f);}
        private static Building Build(TerritorySimulation g,int owner,int x,int y,BuildingKind kind)
        {int cell=g.World.At(x,y);Check(g.Construct(owner,cell,kind).success,"Construir "+kind+" en "+x+","+y);return g.BuildingAt(cell);}
        private static StrategicProjectile Threat(TerritorySimulation g,int id,WeaponKind kind=WeaponKind.Atomic,int owner=-1,int targetX=190,float progress=.65f)
        {var p=new StrategicProjectile{id=id,owner=owner<0?g.PlayerFaction:owner,origin=g.World.At(60,60),target=g.World.At(targetX,60),targetNation=targetX<200?0:1,kind=kind,duration=10,age=progress*10};g.Projectiles.Add(p);return p;}
        public static void Run()
        {
            checks=0;var prices=Fixture();int f=prices.PlayerFaction;double[] expected={125000,250000,500000,1000000,1000000};int[] xs={20,42,64,86,108};
            for(int i=0;i<5;i++){Check(prices.ConstructionPrice(f,BuildingKind.Factory)==expected[i],"Escalera de fábrica "+(i+1));Build(prices,f,xs[i],90,BuildingKind.Factory);}Tick(prices,5);Check(prices.ConstructionPrice(f,BuildingKind.Factory,prices.World.At(20,90))==250000,"Mejorar se calcula aparte del contador de fábricas nuevas");
            Check(prices.ConstructionPrice(0,BuildingKind.SAM)==1500000,"Primer SAM 1.5 M");Build(prices,0,170,60,BuildingKind.SAM);Check(prices.ConstructionPrice(0,BuildingKind.SAM)==3000000,"Segundo SAM 3 M");
            var isolated=Fixture();f=isolated.PlayerFaction;Build(isolated,f,40,40,BuildingKind.Factory);Tick(isolated,30);Check(isolated.Trains.Count==0&&isolated.Ledgers[f].landTrade==0,"Fábrica aislada sin trenes ni ingresos ficticios");
            var close=Fixture();f=close.PlayerFaction;Build(close,f,40,40,BuildingKind.Factory);Build(close,f,48,40,BuildingKind.City);Tick(close,15);Check(close.TradeRoutes.Any(r=>!r.naval),"Las ciudades cercanas también se conectan");
            var far=Fixture();f=far.PlayerFaction;far.Rules.factoryConnectionRadius=60;Build(far,f,30,40,BuildingKind.Factory);Build(far,f,110,40,BuildingKind.City);Tick(far,15);Check(far.TradeRoutes.Count==0,"No enlazar fuera del radio configurado");
            var existing=Fixture();f=existing.PlayerFaction;existing.Rules.factoryConnectionMinimum=0;Build(existing,f,40,40,BuildingKind.Factory);Build(existing,f,48,40,BuildingKind.City);Tick(existing,15);Check(existing.TradeRoutes.Count>0,"Red anterior cercana disponible");existing.Rules.factoryConnectionMinimum=15;Tick(existing,5);Check(existing.TradeRoutes.Count>0,"La separación nueva no borra conexiones ya construidas en campañas anteriores");
            var diagonal=Fixture();f=diagonal.PlayerFaction;Build(diagonal,f,25,30,BuildingKind.Factory);Build(diagonal,f,95,75,BuildingKind.City);Tick(diagonal,10);Check(diagonal.TradeRoutes.Any(r=>!r.naval),"El alcance de fábrica es circular y no un diamante Manhattan");
            var water=Fixture(true);f=water.PlayerFaction;Build(water,f,110,60,BuildingKind.Factory);Build(water,f,140,60,BuildingKind.City);Tick(water,20);Check(water.TradeRoutes.Count==0&&water.Trains.Count==0,"No tender vías sobre un canal de mar");
            var network=Fixture();f=network.PlayerFaction;var factory=Build(network,f,40,40,BuildingKind.Factory);Build(network,f,70,40,BuildingKind.City);Build(network,f,55,16,BuildingKind.Port);Tick(network,24);
            Check(network.ConnectionsFor(factory.id)>0&&network.Trains.Count>0&&network.Ledgers[f].landTrade>0,"Red mixta genera trenes lógicos y paga entregas");
            Check(network.TradeDeliveries.All(d=>d.ownerGold==10000&&d.receiverGold==0)&&network.TradeDeliveries.Sum(d=>d.ownerGold)==network.Ledgers[f].landTrade,"Pago nacional único y registro de vehículo/origen/destino");
            Check(network.TradeRoutes.All(r=>r.naval||r.length<=network.FactoryConnectionPathLimit+.01f)&&network.NavigationNodesLastTick<=network.Rules.navigationNodesPerTick,"Límites de longitud y presupuesto de navegación");
            int routes=network.TradeRoutes.Count,vehicles=network.Trains.Count;double gold=network.Gold[f];Check(network.Construct(f,factory.cell,BuildingKind.Factory).success,"Mejora de fábrica aceptada");double paid=network.Gold[f];Tick(network,2);Check(network.TradeRoutes.Count==routes&&network.Trains.Count==vehicles&&network.Gold[f]==paid&&paid<gold,"Mejora conserva vías/vehículos y pausa cobros");Tick(network,4);Check(factory.level==2,"Mejora conserva límite y aumenta nivel");
            var saved=TerritorySimulation.RestoreCampaign(network.World,network.CaptureCampaign());Check(saved.Trains.Count==network.Trains.Count&&saved.TradeDeliveries.Count==network.TradeDeliveries.Count,"Guardado completo de flota y registro de entregas");Tick(network,3);Tick(saved,3);Check(Math.Abs(saved.Gold[f]-network.Gold[f])<.01,"Continuación de flota sin duplicar cobros");
            network.PreviewFactoryConnections(f,network.World.At(100,70));Tick(network,2);Check(network.TradePreview.Any(p=>p.path!=null),"Previsualización contiene rutas terrestres verificadas");
            var foreign=Fixture();f=foreign.PlayerFaction;Build(foreign,f,110,60,BuildingKind.Factory);var foreignCity=Build(foreign,0,145,60,BuildingKind.City);Tick(foreign,22);Check(foreign.TradeDeliveries.Any(d=>d.ownerGold==25000&&d.receiverGold==12500),"Comercio internacional paga cantidades configuradas a ambos extremos");double earned=foreign.Ledgers[f].landTrade;foreign.SetEmbargo(f,0,true);Tick(foreign,12);Check(foreign.Ledgers[f].landTrade==earned&&!foreign.Trains.Any(),"Embargo detiene futuras entregas y conserva el historial");
            foreign.SetEmbargo(f,0,false);foreign.ProposeAlliance(f,0);foreign.AnswerAlliance(0,f,true);Tick(foreign,22);Check(foreign.TradeDeliveries.Any(d=>d.ownerGold==50000),"Alianza aplica recompensa Atlas configurada");
            foreign.Options.teams=true;foreign.Teams[f]=foreign.Teams[0];Check(foreign.TrainStopReward(f,foreignCity.id)==25000,"Compañero de equipo usa recompensa de equipo y no la de alianza bilateral");
            var hub=Fixture();f=hub.PlayerFaction;var hubFactory=Build(hub,f,70,70,BuildingKind.Factory);foreach(var pos in new[]{new Vector2Int(30,30),new Vector2Int(60,30),new Vector2Int(100,30),new Vector2Int(110,60),new Vector2Int(30,65),new Vector2Int(30,100),new Vector2Int(65,110),new Vector2Int(100,110)})Build(hub,f,pos.x,pos.y,BuildingKind.City);Tick(hub,25);Check(hub.ConnectionsFor(hubFactory.id)==8,"La fábrica conecta las ocho ciudades dentro del alcance sin límite de tres");
            Check(Mathf.Abs(TerritorySimulation.IndustrialSaturation(560)-.5f)<.001f,"Saturación mundial con punto medio configurable");float atlas=foreign.FactoryDispatchInterval(foreign.BuildingAt(foreign.World.At(110,60)));foreign.Rules.factoryProductionProfile=FactoryProductionProfile.OpenFront35Reference;Check(foreign.FactoryDispatchInterval(foreign.BuildingAt(foreign.World.At(110,60)))>atlas,"Producción de referencia separada del intervalo Atlas");
            var combat=Fixture();f=combat.PlayerFaction;var silo=Build(combat,f,65,60,BuildingKind.Silo);var sam=Build(combat,0,180,60,BuildingKind.SAM);Check(combat.SamReadySlots(sam)==0,"SAM en construcción no dispara");Tick(combat,5);Check(combat.SamReadySlots(sam)==1,"Una posición disponible en nivel uno");
            combat.Rules.samBalanceProfile=SamBalanceProfile.OpenFront34Reference;Check(Mathf.Abs(combat.SamRadius(1)-70)<.001f&&Mathf.Abs(combat.SamRadius(5)-102)<.001f&&combat.SamCooldown==9,"Radio y recarga de referencia 34");
            int impacts=0,interceptions=0;combat.StrategicEventRaised+=e=>{if(e.kind==StrategicEventKind.Explosion)impacts++;if(e.kind==StrategicEventKind.Interception)interceptions++;};Check(combat.LaunchWeapon(f,combat.World.At(185,60),WeaponKind.Atomic).success,"Lanzamiento nuclear desde silo real");bool moving=false;for(int i=0;i<100&&combat.Projectiles.Any();i++){combat.Step(.1f);moving|=combat.Interceptors.Count>0;}
            Check(moving&&interceptions==1&&impacts==0&&combat.Radiation.Count==0,"Interceptor viaja, neutraliza y evita explosión posterior");Check(combat.SamReadySlots(sam)==0&&combat.SamReloadRemaining(sam)>0,"La posición consumida entra en recarga real");Tick(combat,9.1f);Check(combat.SamReadySlots(sam)==1,"Recarga a los 90 ciclos de referencia");
            var priority=Fixture();var defender=Build(priority,0,180,60,BuildingKind.SAM);Tick(priority,5);var atom=Threat(priority,1001);var hydro=Threat(priority,1002,WeaponKind.Hydrogen);Check(priority.SamThreatPriority(defender,hydro)>priority.SamThreatPriority(defender,atom),"Prioridad por tipo, distancia de impacto y tiempo restante");priority.Step(.1f);Check(priority.Interceptors.Single().target==hydro.id&&hydro.active,"Se reserva la amenaza prioritaria sin destruirla instantáneamente");
            var overlap=Fixture();Build(overlap,0,180,60,BuildingKind.SAM);Build(overlap,0,185,85,BuildingKind.SAM);Tick(overlap,5);Threat(overlap,2001);Threat(overlap,2002,WeaponKind.Hydrogen);overlap.Step(.1f);Check(overlap.Interceptors.Count==2&&overlap.Interceptors.Select(i=>i.target).Distinct().Count()==2,"Dos SAM asignan objetivos distintos en cobertura solapada");
            var restored=TerritorySimulation.RestoreCampaign(overlap.World,overlap.CaptureCampaign());Check(restored.Interceptors.Count==2&&restored.Interceptors.Select(i=>i.position).SequenceEqual(overlap.Interceptors.Select(i=>i.position)),"Intercepciones en vuelo sobreviven al guardado");Tick(overlap,4);Tick(restored,4);Check(overlap.Radiation.Count==restored.Radiation.Count&&restored.Interceptors.Count==overlap.Interceptors.Count,"Restaurar intercepciones no duplica impactos");
            var slots=Fixture();var five=Build(slots,0,180,60,BuildingKind.SAM);Tick(slots,5);five.level=5;Check(slots.SamReadySlots(five)==1,"Posiciones nuevas respetan preparación sin reiniciar la existente");Tick(slots,slots.SamCooldown+.1f);Check(slots.SamReadySlots(five)==5,"Nivel cinco ofrece cinco posiciones independientes");for(int i=0;i<6;i++)Threat(slots,3000+i);slots.Step(.1f);Check(slots.Interceptors.Count==5&&slots.Interceptors.Select(i=>i.target).Distinct().Count()==5,"Ataque masivo satura cinco posiciones sin disparos infinitos");
            var outside=Fixture();var shortSam=Build(outside,0,180,60,BuildingKind.SAM);Tick(outside,5);Threat(outside,4001,targetX:255,progress:1);Check(!outside.SamCovers(shortSam,outside.Projectiles[0]),"No detectar fuera del radio real");
            var diagonalThreat=new StrategicProjectile{id=4999,owner=outside.PlayerFaction,origin=outside.World.At(220,100),target=outside.World.At(220,100),duration=100};Check(outside.SamCovers(shortSam,diagonalThreat),"Cobertura SAM circular coincide con el aro en diagonales");
            var mirv=Fixture();Build(mirv,0,180,60,BuildingKind.SAM);Tick(mirv,5);Threat(mirv,5001,WeaponKind.Warhead);Threat(mirv,5002,WeaponKind.MIRV);mirv.Step(.1f);Check(!mirv.Rules.samInterceptsMIRV&&mirv.Interceptors.Count==0,"MIRV y ojivas sin intercepción predeterminada");mirv.Rules.samInterceptsMIRV=true;mirv.Step(.1f);Check(mirv.Interceptors.Single().target==5001,"Perfil experimental intercepta ojivas individuales");
            var allied=Fixture();f=allied.PlayerFaction;var allySam=Build(allied,0,180,60,BuildingKind.SAM);Tick(allied,5);allied.ProposeAlliance(f,0);allied.AnswerAlliance(0,f,true);Threat(allied,6001);allied.Step(.1f);Check(allied.Interceptors.Count==0,"No disparar contra aliados");
            var arc=Fixture();var rocket=Threat(arc,7001);Vector3 begin=arc.ProjectilePosition(rocket,0),middle=arc.ProjectilePosition(rocket,.5f),end=arc.ProjectilePosition(rocket,1);Check(middle.y>Mathf.Max(begin.y,end.y)+10&&Mathf.Abs(middle.z-(begin.z+end.z)*.5f)>1,"Trayectoria elevada y curva visible desde cámara aérea");
            Check(FrontierPrototype.MapWidth==3110&&FrontierPrototype.MapHeight==1555,"Tierra nueva reducida aproximadamente 28% en ambos ejes");
            string output=Environment.GetEnvironmentVariable("FRONTIER_OUTPUT")??Path.GetFullPath("Builds");File.WriteAllText(Path.Combine(output,"industrial-defence-validation.json"),"{\"passed\":true,\"assertions\":"+checks+",\"savedTrains\":"+saved.Trains.Count+",\"savedInterceptors\":2}");Debug.Log("INDUSTRIAL_DEFENCE_VALIDATION_OK "+checks);
        }
    }
}
